// 시라츠키 학원 고등부 공식 홈페이지 v1
// VS Code에서 index.html을 열어 바로 사용할 수 있습니다.

let uploadedPhotoData = "";
let isDownloadingCard = false;

const SCHOOL_LOGO_DATA_URL = "data:image/png;base64,";

function showPage(id) {
  document.querySelectorAll(".page").forEach(page => {
    page.classList.remove("active");
  });

  const target = document.getElementById(id);
  if (target) target.classList.add("active");

  document.querySelectorAll(".nav-btn").forEach(btn => {
    btn.classList.toggle("active", btn.dataset.page === id);
  });

  window.scrollTo({ top: 0, behavior: "smooth" });
}

function getStudentValues() {
  const height = document.getElementById("heightInput")?.value || "";
  const weight = document.getElementById("weightInput")?.value || "";

  return {
    name: document.getElementById("nameInput")?.value || "---",
    birth: document.getElementById("birthInput")?.value || "---",
    grade: document.getElementById("gradeInput")?.value || "---",
    klass: document.getElementById("classInput")?.value || "---",
    club: document.getElementById("clubInput")?.value || "---",
    body: height || weight ? `${height || "---"}cm · ${weight || "---"}kg` : "---"
  };
}

function issueStudentId() {
  const data = getStudentValues();

  document.getElementById("cardName").textContent = data.name;
  document.getElementById("cardBirth").textContent = data.birth;
  document.getElementById("cardGrade").textContent = data.grade;
  document.getElementById("cardClass").textContent = data.klass;
  document.getElementById("cardClub").textContent = data.club;
  document.getElementById("cardBody").textContent = data.body;

  const card = document.getElementById("studentCard");
  if (card) {
    card.classList.remove("issued");
    void card.offsetWidth;
    card.classList.add("issued");
  }
}

document.getElementById("photoInput")?.addEventListener("change", function(event) {
  const file = event.target.files[0];
  if (!file) return;

  const reader = new FileReader();

  reader.onload = function(e) {
    uploadedPhotoData = e.target.result;

    const photo = document.getElementById("cardPhoto");
    const text = document.getElementById("photoText");

    photo.src = uploadedPhotoData;
    photo.style.display = "block";
    text.style.display = "none";
  };

  reader.readAsDataURL(file);
});

document.getElementById("cardFlip")?.addEventListener("click", flipCard);

function flipCard() {
  const flip = document.getElementById("cardFlip");
  if (flip) flip.classList.toggle("flipped");
}

function checkPassword() {
  const pw = document.getElementById("password").value;
  const terminal = document.getElementById("terminal");
  const adminDocs = document.getElementById("adminDocs");

  if (pw === "NOAH") {
    terminal.textContent =
`ACCESS GRANTED

管理者認証完了。
A-2 権限確認。

Project ARK 중앙 시스템 「NOAH」가 기동되었습니다.

관리자 전용 문서 보관소를 개방합니다.`;
    adminDocs.classList.remove("hidden");
  } else if (pw === "ARK") {
    terminal.textContent =
`ACCESS PARTIAL

부분 권한이 확인되었습니다.

일부 문서 제목만 열람 가능합니다.
상세 문서 열람에는 A-2 권한이 필요합니다.`;
    adminDocs.classList.remove("hidden");
  } else {
    terminal.textContent =
`ACCESS DENIED

권한을 확인할 수 없습니다.
비밀번호를 다시 입력하십시오.`;
    adminDocs.classList.add("hidden");
  }
}

function openRouteModal() {
  document.getElementById("routeModal")?.classList.remove("hidden");
}

function closeRouteModal(event) {
  if (!event) return;
  if (event.target.id === "routeModal" || event.target.classList.contains("modal-close")) {
    document.getElementById("routeModal")?.classList.add("hidden");
  }
}

/* Canvas helpers */

function roundedRect(ctx, x, y, width, height, radius) {
  const r = Math.min(radius, width / 2, height / 2);
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + width - r, y);
  ctx.quadraticCurveTo(x + width, y, x + width, y + r);
  ctx.lineTo(x + width, y + height - r);
  ctx.quadraticCurveTo(x + width, y + height, x + width - r, y + height);
  ctx.lineTo(x + r, y + height);
  ctx.quadraticCurveTo(x, y + height, x, y + height - r);
  ctx.lineTo(x, y + r);
  ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.closePath();
}

function loadImage(src) {
  return new Promise(resolve => {
    const image = new Image();
    image.onload = () => resolve(image);
    image.onerror = () => resolve(null);
    image.src = src;
  });
}

async function drawLogo(ctx, x, y, size) {
  if (SCHOOL_LOGO_DATA_URL) {
    const logo = await loadImage(SCHOOL_LOGO_DATA_URL);
    if (logo) {
      ctx.drawImage(logo, x, y, size, size);
      return;
    }
  }

  const cx = x + size / 2;
  const cy = y + size / 2;

  ctx.save();
  ctx.fillStyle = "#071c36";
  roundedRect(ctx, x, y, size, size, 20);
  ctx.fill();
  ctx.fillStyle = "#ffffff";
  ctx.font = `bold ${Math.floor(size * 0.55)}px serif`;
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText("白", cx, cy);
  ctx.restore();
}

async function drawPhoto(ctx, dataUrl, x, y, width, height) {
  ctx.save();
  ctx.fillStyle = "#edf6fd";
  roundedRect(ctx, x, y, width, height, 24);
  ctx.fill();

  if (dataUrl) {
    const image = await loadImage(dataUrl);
    if (image) {
      roundedRect(ctx, x, y, width, height, 24);
      ctx.clip();

      const imgRatio = image.width / image.height;
      const boxRatio = width / height;

      let dw = width;
      let dh = height;
      let dx = x;
      let dy = y;

      if (imgRatio > boxRatio) {
        dh = height;
        dw = height * imgRatio;
        dx = x - (dw - width) / 2;
      } else {
        dw = width;
        dh = width / imgRatio;
        dy = y - (dh - height) / 2;
      }

      ctx.drawImage(image, dx, dy, dw, dh);
    }
  } else {
    ctx.fillStyle = "#0d477a";
    ctx.font = "bold 58px sans-serif";
    ctx.textAlign = "center";
    ctx.fillText("PHOTO", x + width / 2, y + height / 2 + 18);
  }

  ctx.restore();

  ctx.strokeStyle = "#8dbfe0";
  ctx.lineWidth = 5;
  roundedRect(ctx, x, y, width, height, 24);
  ctx.stroke();
}

function drawField(ctx, label, value, x, y, endX) {
  ctx.fillStyle = "#071c36";
  ctx.font = "bold 42px sans-serif";
  ctx.textAlign = "left";
  ctx.fillText(label, x, y);

  ctx.fillStyle = "#0d477a";
  ctx.font = "38px sans-serif";
  ctx.fillText(value || "---", x + 220, y);

  ctx.strokeStyle = "rgba(13, 95, 168, 0.28)";
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(x + 220, y + 18);
  ctx.lineTo(endX, y + 18);
  ctx.stroke();
}

async function downloadCard() {
  if (isDownloadingCard) return;
  isDownloadingCard = true;

  try {
    issueStudentId();

    const canvas = document.getElementById("downloadCanvas");
    const ctx = canvas.getContext("2d");
    const data = getStudentValues();

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const x = 90;
    const y = 90;
    const w = 2020;
    const h = 1180;

    const bg = ctx.createLinearGradient(x, y, x + w, y + h);
    bg.addColorStop(0, "#ffffff");
    bg.addColorStop(1, "#f2faff");

    ctx.fillStyle = bg;
    roundedRect(ctx, x, y, w, h, 70);
    ctx.fill();

    ctx.strokeStyle = "#83bfe5";
    ctx.lineWidth = 7;
    roundedRect(ctx, x, y, w, h, 70);
    ctx.stroke();

    // Navy header band
    const head = ctx.createLinearGradient(x, y, x + w, y + 250);
    head.addColorStop(0, "#071c36");
    head.addColorStop(1, "#0d5fa8");
    ctx.fillStyle = head;
    roundedRect(ctx, x, y, w, 250, 70);
    ctx.fill();
    ctx.fillRect(x, y + 170, w, 120);

    await drawLogo(ctx, x + 80, y + 50, 150);

    ctx.fillStyle = "#ffffff";
    ctx.font = "bold 82px serif";
    ctx.textAlign = "left";
    ctx.fillText("白月学園高等部", x + 270, y + 115);

    ctx.font = "bold 36px sans-serif";
    ctx.fillText("SHIRATSUKI ACADEMY HIGH SCHOOL", x + 276, y + 172);

    ctx.font = "bold 44px sans-serif";
    ctx.textAlign = "right";
    ctx.fillText("STUDENT ID CARD", x + w - 80, y + 138);

    // watermark
    ctx.save();
    ctx.globalAlpha = 0.055;
    ctx.fillStyle = "#0d477a";
    ctx.font = "430px serif";
    ctx.textAlign = "center";
    ctx.fillText("白", x + 1510, y + 760);
    ctx.restore();

    await drawPhoto(ctx, uploadedPhotoData, x + 90, y + 360, 440, 540);

    const startX = x + 650;
    drawField(ctx, "氏名", data.name, startX, y + 410, x + w - 150);
    drawField(ctx, "生年月日", data.birth, startX, y + 525, x + w - 150);
    drawField(ctx, "学年", data.grade, startX, y + 640, x + w - 150);
    drawField(ctx, "組", data.klass, startX, y + 755, x + w - 150);
    drawField(ctx, "部活動", data.club, startX, y + 870, x + w - 150);
    drawField(ctx, "身長・体重", data.body, startX, y + 985, x + w - 150);

    ctx.strokeStyle = "rgba(13, 95, 168, 0.55)";
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(x + 90, y + 1040);
    ctx.lineTo(x + w - 90, y + 1040);
    ctx.stroke();

    ctx.fillStyle = "#0d477a";
    ctx.font = "34px sans-serif";
    ctx.textAlign = "left";
    ctx.fillText("発行日 20XX.07.18", x + 90, y + 1115);

    ctx.textAlign = "right";
    ctx.fillText("本証は白月学園高等部の生徒証明書です。", x + w - 90, y + 1115);

    const link = document.createElement("a");
    link.download = "Shiratsuki_Student_ID.png";
    link.href = canvas.toDataURL("image/png");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  } catch (error) {
    alert("학생증 저장 실패: " + error.message);
  } finally {
    setTimeout(() => {
      isDownloadingCard = false;
    }, 1200);
  }
}
